+func TestRedHatAdvisoryIdentifier(t *testing.T) {
+	for _, tt := range []struct {
+		family, title, want string
+	}{
+		{constant.RedHat, "RHSA-2024:1234: security update", "RHSA-2024:1234"},
+		{constant.CentOS, "RHBA-2024:1234: bug fix", "RHBA-2024:1234"},
+		{constant.Alma, "RHSA-2024:1234: security update", "RHSA-2024:1234"},
+		{constant.Rocky, "RHSA-2024:1234: security update", "RHSA-2024:1234"},
+		{constant.Oracle, "ELSA-2024-1234: security update", "ELSA-2024-1234"},
+		{constant.Amazon, "ALAS2-2024-1234: security update", "ALAS2-2024-1234"},
+		{constant.Fedora, "FEDORA-2024-1234: security update", "FEDORA-2024-1234"},
+		{constant.RedHat, "ELSA-2024-1234: security update", ""},
+		{constant.Oracle, "RHSA-2024:1234: security update", ""},
+		{constant.Fedora, "", ""},
+	} {
+		got := (RedHatBase{Base: Base{family: tt.family}}).convertToDistroAdvisory(&ovalmodels.Definition{Title: tt.title})
+		if tt.want == "" {
+			if got != nil {
+				t.Errorf("%s %q: expected nil, got %#v", tt.family, tt.title, got)
+			}
+		} else if got == nil || got.AdvisoryID != tt.want {
+			t.Errorf("%s %q: expected %s, got %#v", tt.family, tt.title, tt.want, got)
+		}
+	}
+}
+
+func TestRedHatUpdatePreservesFixState(t *testing.T) {
+	r := models.ScanResult{ScannedCves: models.VulnInfos{}}
+	def := defPacks{
+		def: ovalmodels.Definition{
+			Title:    "RHSA-2024:1234: security update",
+			Advisory: ovalmodels.Advisory{Cves: []ovalmodels.Cve{{CveID: "CVE-2024-1234"}}},
+		},
+		binpkgFixstat: map[string]fixStat{"pkg": {notFixedYet: true, fixState: "Fix deferred", fixedIn: "2.0"}},
+	}
+	o := RedHatBase{Base: Base{family: constant.RedHat}}
+	o.update(&r, def)
+	v := r.ScannedCves["CVE-2024-1234"]
+	if len(v.DistroAdvisories) != 1 || v.DistroAdvisories[0].AdvisoryID != "RHSA-2024:1234" {
+		t.Fatalf("unexpected advisories: %#v", v.DistroAdvisories)
+	}
+	if len(v.AffectedPackages) != 1 || v.AffectedPackages[0] != (models.PackageFixStatus{Name: "pkg", NotFixedYet: true, FixState: "Fix deferred", FixedIn: "2.0"}) {
+		t.Fatalf("unexpected package status: %#v", v.AffectedPackages)
+	}
+	def.def.Title = "Unsupported title"
+	o.update(&r, def)
+	if len(r.ScannedCves["CVE-2024-1234"].DistroAdvisories) != 1 {
+		t.Fatalf("unsupported advisory was added: %#v", r.ScannedCves["CVE-2024-1234"].DistroAdvisories)
+	}
+}
